def ignore_retry_requests(
    response: Dict[str, Dict[str, int]]
) -> Optional[Dict[str, Dict[str, int]]]:
    SKIP_RECORD = [408, 429]
    if response["status"]["code"] in SKIP_RECORD:
        return None  # do not record

    return response


